/**
 * Every limit the three launch projects disclose, in one list.
 *
 * Each row is taken from a launch project's `docs/THREATS.md`: its trust roots (section 2), the
 * limits of each contract, the limits of the build and of its tests, what a launch inherits from
 * the ones before it, and what is not verified. `limit` is the document's own heading for the
 * entry (for a trust root: "Trusts" and the party) and `detail` is how its text goes on, with the
 * names of tests left out; where the heading is the start of a sentence, `detail` finishes it, and
 * where the entry is a list, `detail` gives the head of each item. Every sentence is the
 * document's own, in the document's order. The document has the whole of each entry. Nothing is added and nothing is left out:
 * `test/limits.test.ts` reads the three documents, when they are in the repository beside this app,
 * and fails if an entry of theirs is missing here or worded otherwise.
 *
 * `since` is this site's own note, used only where a document's statement has been overtaken by
 * something that happened after it was written. The document's words are kept beside it.
 */

export type LimitLaunch = "A" | "B" | "C";

export interface DisclosedLimit {
  launch: LimitLaunch;
  /** The entry's id in its document: T for a trust root, N for "not verified", I for "inherited". */
  id: string;
  section: string;
  limit: string;
  detail: string;
  since?: string;
}

/** The document each launch's rows come from, as a path in the repository. */
export const THREATS_DOCUMENT: Record<LimitLaunch, string> = {
  A: "launches/a-payroll/docs/THREATS.md",
  B: "launches/b-desk/docs/THREATS.md",
  C: "launches/c-company/docs/THREATS.md",
};

// prettier-ignore
export const DISCLOSED_LIMITS: readonly DisclosedLimit[] = [
  { launch: "A", id: "T1", section: "Trust roots", limit: "Trusts the oracle signer, 0x5598aa9146215bc13eb26f2c692ad1461fd32982, one externally owned key", detail: "Trusted for: Signing every answer. Questions accepts an answer only with its signature. If it fails: A wrong or compromised key can write wrong values into any feed, and so into the Jobs Report." },
  { launch: "A", id: "T2", section: "Trust roots", limit: "Trusts IdentityMD's Intake, version 2, 0xa43e6f75ee006411f79ac1c84120606c2330de82, and its owner", detail: "Trusted for: Taking the price and recording the request. Its owner sets the price and the callback gas. If it fails: A price above a feed's maxPrice stops that feed's requests." },
  { launch: "A", id: "T3", section: "Trust roots", limit: "Trusts the Intake's writer, 0x3d3c0df7c1a17d384545e9d7c8228897bd9625cb (the same for both versions of the Intake), and the service behind it", detail: "Trusted for: Calling complete, which delivers the answer, and doing it in time: an answer is useless to a round that was closed before it came. Marking a request completed." },
  { launch: "A", id: "T4", section: "Trust roots", limit: "Trusts the IMD token, 0xd34a99bc0f67ae1bbd63c660e6d0b0dd03e263b7, and its owner, 0x047F606fD5b2BaA5f5C6c4aB8958E45CB6B054B7", detail: "Trusted for: Being a plain ERC-20 with no fee on transfer and no hooks. If it fails: Both contracts book what actually arrived, by balance difference. IMD on Ethereum is a LayerZero OFT (BridgedFP), not a proxy: its supply here is created only when LayerZero's endpoint delivers a transfer from the contract the token names as its peer on another chain. The owner names those peers (setPeer) and who sets how their messages are verified (setDelegate; the delegate is the owner itself), so it can have IMD created on Ethereum through a contract of its choosing. New IMD takes nothing from any meter, stream, seat share or tip that Questions and Payroll hold; it changes only what each is worth." },
  { launch: "A", id: "T5", section: "Trust roots", limit: "Trusts sIMD, 0x9efa934d9fad4ae28c998a40195646b965a97247. It has no owner: owner() is the zero address and paused() is false (read 13 October 2026)", detail: "Trusted for: Receiving the stakers' stream by plain transfer and pricing its shares from its IMD balance. And one property Payroll cannot enforce: a holder cannot leave in the block it staked in (P2)." },
  { launch: "A", id: "T6", section: "Trust roots", limit: "Trusts the seat token, 0x0000ec93127baa929e58e97dd0095a2bfb38ec1d", detail: "Trusted for: Saying who owns a seat. Payroll pays whoever ownerOf names at the moment of a claim. If it fails: A seat whose owner is never named again keeps its share of the seat pool in Payroll for good." },
  { launch: "A", id: "T7", section: "Trust roots", limit: "Trusts the seat Adapter, 0xde152afb7db5373f34876e1499fbd893a82dd336, an upgradeable proxy, and whoever controls it", detail: "Trusted for: Saying which seat an agent is bound to. Only tips depend on it." },
  { launch: "A", id: "T8", section: "Trust roots", limit: "Trusts Questions, as Payroll and JobsReport see it", detail: "Trusted for: Payroll hands it at most one runway per house feed at a time. JobsReport copies its answers. If it fails: It is this launch's own immutable code." },
  { launch: "A", id: "T9", section: "Trust roots", limit: "Trusts the launch pipeline and the ProjectFactory", detail: "Trusted for: Creating the three contracts with the manifest's arguments, in order. If it fails: A wrong argument is permanent. docs/LAUNCH.md says how to read every argument back after the launch." },
  { launch: "A", id: "T10", section: "Trust roots", limit: "Trusts keepers: whoever calls request, submit, print, drip, fundFeeds, abandon", detail: "Trusted for: Liveness only. If it fails: With no keeper nothing moves and nothing is lost: feeds go stale, the stream waits, and feed budget whose wait is over stays in Payroll until somebody calls fundFeeds." },
  { launch: "A", id: "T11", section: "Trust roots", limit: "Trusts OpenZeppelin Contracts 5.5.0 (vendored in lib/), solc 0.8.26, and the EIP-2935 history contract that Blockhash reads for a block hash older than 256 blocks", detail: "Trusted for: Correctness of the library code and the compiler." },
  { launch: "A", id: "T12", section: "Trust roots", limit: "Trusts the oracle's rule for computing questionHash", detail: "Trusted for: Staying as it is. Questions rebuilds the hash on chain from a rule we reconstructed from 23 attested requests and checked against the three proofs of the house feeds (docs/DEVIATIONS.md, D6)." },
  { launch: "A", id: "T13", section: "Trust roots", limit: "Trusts the oracle's panel for the employers feed: seven agents, each holding one seat", detail: "Trusted for: Reading the chain as the question's method says and answering what they find. For this one feed the oracle signs what five of the seven agree on and does not recompute it (F4)." },
  { launch: "A", id: "Q1", section: "Limits of Questions", limit: "A request is paid for whether or not it is answered.", detail: "The Intake never refunds. A refused body, a panel that does not agree, a request the service never serves: each costs the meter the price (0.5 IMD today)." },
  { launch: "A", id: "Q2", section: "Limits of Questions", limit: "A caller can make a round go unserved, at its own expense.", detail: "The service serves only the first Intake request of a transaction. request refuses a second request of its own in one transaction, but it cannot see a request its caller bought from the Intake earlier in the same transaction." },
  { launch: "A", id: "Q3", section: "Limits of Questions", limit: "submit takes any signed answer to the feed's question about the round's blocks.", detail: "Nothing on chain ties an attestation to the request a round paid for." },
  { launch: "A", id: "Q4", section: "Limits of Questions", limit: "The opener keeps the tip of every answered round.", detail: "The launch audit reproduced an observer taking the opener's tip with a public signature. _settle now always credits the keeper recorded by request, regardless of who submits. Submission itself earns no reward." },
  { launch: "A", id: "Q5", section: "Limits of Questions", limit: "A returned tip is shared by whoever holds the meter's shares when the round is closed.", detail: "It comes back as balance and no share is minted, so every share is worth a little more afterwards." },
  { launch: "A", id: "Q6", section: "Limits of Questions", limit: "In two rare cases part of a returned tip belongs to nobody.", detail: "A share must never be worth more than one wei." },
  { launch: "A", id: "Q7", section: "Limits of Questions", limit: "Failed rounds back the feed off.", detail: "After each failed round in a row the feed waits twice as long before it may ask again, up to 32 times its cadence: about a month for a daily feed, about 31 weeks for the weekly one." },
  { launch: "A", id: "Q8", section: "Limits of Questions", limit: "Silence has a bounded deadline that includes the requested validity.", detail: "submit opens at thirty minutes. Silence permits abandon at requestedAt + 12 hours + validFor + 5 minutes + 1 second; all house feeds therefore wait 36 h 5 min 1 s. The twelve hours allow for signing, then an answer signed within that allowance has its whole requested validity to arrive." },
  { launch: "A", id: "Q9", section: "Limits of Questions", limit: "A WHEN gate is read once, inside the transaction that asks.", detail: "A gate on a value that can be moved and moved back within one transaction (a pool balance, a spot price) can be opened by the caller at will. The three house feeds have no gate." },
  { launch: "A", id: "Q10", section: "Limits of Questions", limit: "One attestation can answer one round of each of two feeds", detail: "that hold the same question and ask about the same blocks. Each feed paid for a request of its own, and what one does with an answer never takes it away from the other." },
  { launch: "A", id: "Q11", section: "Limits of Questions", limit: "A feed can be created to waste its funders' IMD.", detail: "createFeed checks what can be checked (panel, quorum, window, lag, tip at most maxPrice, the body's shape and length). It cannot check that a question is answerable." },
  { launch: "A", id: "Q12", section: "Limits of Questions", limit: "IMD sent to Questions by plain transfer is not on any meter", detail: "and can be withdrawn by nobody. There is no sweep on purpose: crediting it to a meter would let a sender change what a share is worth." },
  { launch: "A", id: "Q13", section: "Limits of Questions", limit: "An old catch-up window's closing block hash is not checked.", detail: "When a window ends more than 8,191 blocks back, the chain no longer serves its hash, zero is stored, and the answer's blockHash is accepted as signed." },
  { launch: "A", id: "Q14", section: "Limits of Questions", limit: "What is asked after a failed round depends on the feed.", detail: "A feed whose windows tile and that already has an answer starts its next window at the same block and ends it at a newer one, so no block is skipped." },
  { launch: "A", id: "Q15", section: "Limits of Questions", limit: "Smaller points.", detail: "costOf is zero while no request can be bought (unknown feed, action not sold, price unreadable or above the feed's cap). A feed can only be about the chain it is on." },
  { launch: "A", id: "F1", section: "Limits of the three house feeds", limit: "Each body was accepted by the live oracle once.", detail: "On 12 and 13 October 2026 one request per feed was bought with exactly the bytes Questions sends, and all three were attested. That proves the bodies, the question hash built on chain, the answer types and the panel figures." },
  { launch: "A", id: "F2", section: "Limits of the three house feeds", limit: "Hires counts transfers, not purchases.", detail: "It counts every IMD Transfer log whose recipient is the fee payee, transfers of zero included, because a log-count filter reaches indexed arguments only." },
  { launch: "A", id: "F3", section: "Limits of the three house feeds", limit: "Payrolls and the ranking count every transfer to the fee payee", detail: ", whatever it paid for, including this launch's own purchases of answers: Questions pays the fee payee for every request, so it is itself one of the senders the ranking sees. An address can buy a place among the Employers of the Week by paying the fee payee, and a sender of a zero-value transfer can appear when fewer than three addresses paid in the week." },
  { launch: "A", id: "F4", section: "Limits of the three house feeds", limit: "The employers feed is judged by a panel, and the two daily feeds are not.", detail: "This is the difference a reader of the feeds most needs to know." },
  { launch: "A", id: "F5", section: "Limits of the three house feeds", limit: "Their parameters are part of their ids", detail: ", and the ids are constructor arguments of JobsReport and Payroll. A feed whose body the oracle later stops accepting cannot be replaced without launching the three contracts again." },
  { launch: "A", id: "P1", section: "Limits of Payroll", limit: "Unclaimed seat revenue follows the seat.", detail: "Claims pay the current ownerOf, including revenue accrued before a transfer. Anyone may initiate payment to an ordinary wallet. For a seat held by code, that holder must call itself; another caller gets ContractOwnerMustClaim from claimSeat or claimTip, and claimSeats skips it." },
  { launch: "A", id: "P2", section: "Limits of Payroll", limit: "A visitor to sIMD takes a staker's share of every drip it attends.", detail: "Open, by decision: this is the medium finding of the second audit (docs/AUDITS.md, 2.1), acknowledged and not closed." },
  { launch: "A", id: "P3", section: "Limits of Payroll", limit: "A booking can delay money that was already vesting.", detail: "Open, by decision: the low finding 1.3 and 2.3 of the audits; the rule is the build brief's decision 2." },
  { launch: "A", id: "P4", section: "Limits of Payroll", limit: "Tips depend on the Adapter (T7).", detail: "Only the first 16 agent ids of a tip share it; an id listed twice is credited twice; ids are not checked when the tip arrives." },
  { launch: "A", id: "P5", section: "Limits of Payroll", limit: "A seat nobody owns keeps its share.", detail: "If the seat token never names an owner for a seat again, that seat's share of the seat pool stays in Payroll for good. Tips bound to such a seat are different: they can be swept after their wait." },
  { launch: "A", id: "P6", section: "Limits of Payroll", limit: "Payroll never takes IMD back from a meter.", detail: "What it places on a house feed's meter is spent by that feed or stays there. The most that can sit on a meter that has stopped being used is one runway: 14 requests for each daily feed and 4 for the weekly one, each counted at no more than 2 IMD." },
  { launch: "A", id: "P7", section: "Limits of Payroll", limit: "Feed budget waits, then goes to stakers, and only fundFeeds sends it.", detail: "Budget booked in one fortnight falls due at the second boundary after it, so it waits 14 to 28 days for a meter to need it. Falling due moves no money." },
  { launch: "A", id: "P8", section: "Limits of Payroll", limit: "A tip that falls back to a plain transfer is booked as revenue.", detail: "A caller that cannot complete tip and transfers the IMD plainly has it split 50/30/20 by book, not held for the agents. tip to 16 agents never seen before stays under 600,000 gas, and the dearest tip and pay under the 1,000,000 the hire desk forwards." },
  { launch: "A", id: "P9", section: "Limits of Payroll", limit: "claimSeats takes at most 200 ids.", detail: "A full list of seats never paid before used between 47,600 and 49,400 gas a seat on a mainnet fork on two days, 9.5 to 9.9 million for 200, inside the 16.7 million one transaction may use." },
  { launch: "A", id: "J1", section: "Limits of JobsReport", limit: "It reports what the oracle answered.", detail: "It adds no check of its own on the figures beyond passing over failed rounds, empty or unfinished windows, overlapping windows and answers above 2^128 − 1." },
  { launch: "A", id: "J2", section: "Limits of JobsReport", limit: "A count may cover a shifted window.", detail: "The two daily feeds are bought by separate transactions. When they are requested in the same block the count is exact for its print's period." },
  { launch: "A", id: "J3", section: "Limits of JobsReport", limit: "The streak ends on a catch-up.", detail: "A print over more than 7,500 blocks, which is what a missed day produces, cannot take the best-day record and ends the streak." },
  { launch: "A", id: "J4", section: "Limits of JobsReport", limit: "The crown is decoration.", detail: "Anyone holding the attested list may publish a round's top three, once per round, in any order of rounds. Nothing else in the report depends on it." },
  { launch: "A", id: "B1", section: "Limits of the build", limit: "Questions is 22,963 bytes: 37 under our own 23,000-byte gate and 1,613 under the protocol's limit.", detail: "Nothing of substance can be added to it. That is why Q5 is disclosed and not closed.", since: "Since this was written, IdentityMD's launch pipeline changed Questions before launching it. The contract at its mainnet address has 22,233 bytes of runtime code (read with eth_getCode on 13 October 2026), the figure launches/a-payroll/ADAPTATION.md gives." },
  { launch: "A", id: "B2", section: "Limits of the build", limit: "The launch is about 11.1 million gas in our rehearsal", detail: ", against our gate of 12 million and the protocol's ceiling of 16.7 million." },
  { launch: "A", id: "B3", section: "Limits of the build", limit: "Nothing is called after deployment.", detail: "The three feeds exist only after three transactions that anyone may send; docs/LAUNCH.md holds their calldata. Until then meters cannot be funded and Payroll's feed budget ages toward stakers.", since: "Since this was written, the launch was mined (13 October 2026, block 26,182,869) and the three feeds were created the same day, in blocks 26,183,604 to 26,183,608, by house wallet H1. What each feed holds now is read live on the questions page." },
  { launch: "A", id: "B4", section: "Limits of the build", limit: "Some tests use QuestionsRig", detail: ", which is Questions itself with six added functions that write its storage directly, so that Payroll and JobsReport can be shown round shapes the real contract never produces. No function of Questions is overridden." },
  { launch: "A", id: "N1", section: "Not verified", limit: "Shown since this list was written", detail: "(15 October 2026), on mainnet. IdentityMD's launch pipeline ran to the end. Its audit of the imported code read the code as it was supplied, the fixes of the two audits and the two changed waits included, and raised the four findings that ADAPTATION.md answers. After the pipeline changed the code for three of them, four specialist reviewers and a judge read the adapted code and were accepted (docs/AUDITS.md, last section, lists what all of them reported), and it created the three contracts on 13 October 2026 as IdentityMD launch 1531, in block 26,182,869. The live Intake's writer delivered an answer signed for the launched Questions by the callback: the employers round, requested in block 26,183,622 at 12:38 UTC and answered in block 26,185,017 at 17:18 UTC, 4 hours 40 minutes later (transaction 0xfed277e7525f289f8e8bad0333148c8823f42c779836280189ff874500de051b), and JobsReport.crown recorded the list from it. And the first day's transactions give mainnet gas figures: createFeed 818,553 to 1,118,573, fund 123,194 to 162,206, request 349,971 to 389,145, submit 143,383 and 143,551, print 304,795, crown 171,649, and the Intake's delivery of the callback 162,093. The entries below were written before the launch and are kept as they were. This note answers three of them (a real answer delivered by the live Intake, the launch pipeline itself, and the gas figures), the one on an audit of the code in part, and adds one reading to the one on how fast the writer completes a request." },
  { launch: "A", id: "N2", section: "Not verified", limit: "A real answer delivered by the live Intake to the launched contracts.", detail: "The three house bodies were proven with requests that named no callback, so their answers were signed for no consumer (F1)." },
  { launch: "A", id: "N3", section: "Not verified", limit: "How fast the Intake's writer completes a request.", detail: "The oracle attested the three proofs 52 seconds, 62 seconds and 4 minutes 16 seconds after they were admitted." },
  { launch: "A", id: "N4", section: "Not verified", limit: "How often the panel agrees on the employers question.", detail: "One request, one attestation, in which five members answered and all five agreed. One fewer and the quorum would not have been met." },
  { launch: "A", id: "N5", section: "Not verified", limit: "A catch-up window of the daily feeds.", detail: "The proofs asked about 7,000 blocks. After a missed or failed round the daily feeds ask about up to 21,600." },
  { launch: "A", id: "N6", section: "Not verified", limit: "The launch pipeline itself.", detail: "The factory call is rehearsed on a fork as the launch deployer. The pipeline's own checks before that call are not ours to run." },
  { launch: "A", id: "N7", section: "Not verified", limit: "Whether the service ever completes a request it did not serve", detail: "(one that was not the first of its transaction). The contract handles both cases: submit opens at once if it does, thirty minutes after the request if it does not." },
  { launch: "A", id: "N8", section: "Not verified", limit: "That sIMD keeps its one-block hold.", detail: "It is read from the live contract on a fork (P2). sIMD has no owner, so we know of nobody who could change it, but its source is not in this repository." },
  { launch: "A", id: "N9", section: "Not verified", limit: "An audit of the code as it is now.", detail: "The two audits read commit 5c049e0. The fixes made since (docs/AUDITS.md) have been tested here and have not been audited again. The launch assignment supplied a further four-finding audit; its reproductions and changes are recorded in ADAPTATION.md and still require the independent final review." },
  { launch: "A", id: "N10", section: "Not verified", limit: "Gas figures", detail: "are from tests and from a mainnet fork, not from mainnet transactions." },
  { launch: "B", id: "T1", section: "Trust roots", limit: "Trusts the writer of IdentityMD's WorkRegistry: 0x5dA3054201BC7E241875Ac68173e49C269F76D44 on 11, 12 and 13 October 2026. The registry's admin, 0x047F606fD5b2BaA5f5C6c4aB8958E45CB6B054B7, an account with no code, can appoint another writer or another admin.", detail: "Trusted for: Writing a receipt for a job only when the swarm really produced that record. If it fails: Whoever controls the writer can record a hash for a record of its own making. If it also holds an order as its runner, that record settles the order: every escrow a runner can claim is exposed to that key." },
  { launch: "B", id: "T2", section: "Trust roots", limit: "Trusts the WorkRegistry contract, 0xb6d0a187b050fa5bb0b87033a203f37becf4a775. Its source is not published.", detail: "Trusted for: Answering latest(bytes16) with the hash of the job's newest record, or zero. If it fails: It is treated as untrusted code: called read-only, with 50,000 gas, and believed only when it returns exactly one non-zero word." },
  { launch: "B", id: "T3", section: "Trust roots", limit: "Trusts IdentityMD's swarm and its API", detail: "Trusted for: Deciding what a work record says: its kind, its objective, its state, the agents in its signals. Serving the record's bytes. Keeping the record's form as it was in October 2026. If it fails: A record that says completed for work that was not done settles the order: a proof says what IdentityMD recorded, not that the work is good (P1)." },
  { launch: "B", id: "T4", section: "Trust roots", limit: "Trusts the IMD token, 0xd34a99bc0f67ae1bbd63c660e6d0b0dd03e263b7, and its owner, 0x047F606fD5b2BaA5f5C6c4aB8958E45CB6B054B7: the same account as the WorkRegistry's admin (T1)", detail: "Trusted for: Moving exactly the amount it is asked to: no fee on transfer, no hooks. The desk's sums and CrowdPots' books assume it. If it fails: The desk does not measure what arrived. A token that kept a part of each transfer would leave the desk short. IMD on Ethereum is a LayerZero OFT (BridgedFP), not a proxy: its supply here is created only when LayerZero's endpoint delivers a transfer from the contract the token names as its peer on another chain. The owner names those peers (setPeer) and who sets how their messages are verified (setDelegate; the delegate is the owner itself), so it can have IMD created on Ethereum through a contract of its choosing. New IMD changes no escrow, bond or chip the desk and CrowdPots hold, only what each is worth." },
  { launch: "B", id: "T5", section: "Trust roots", limit: "Trusts Payroll, the contract of HELP WANTED's first launch, at 0x6e4362a5cEc59Eb3F611af6b2d81915CF5b45f1F (IdentityMD launch 1531). It has no owner and no upgrade path. The address is in the manifest; its code was compared with that launch's build (docs/LAUNCH.md, section 6) and its hash is pinned in the fork suite.", detail: "Trusted for: Receiving the fee and the tip, and crediting the tip to the agents named. What happens to that money afterwards is Payroll's own rule, stated under the table. If it fails: It cannot block a settlement. Each of its two calls is offered 1,000,000 gas; whatever it does not take, for any reason, is sent to it by plain transfer." },
  { launch: "B", id: "T6", section: "Trust roots", limit: "Trusts an employer's callback and an order's condition target", detail: "Trusted for: Nothing. If it fails: Both are untrusted. The callback runs last, with 150,000 gas, after every payment; its failure changes nothing." },
  { launch: "B", id: "T7", section: "Trust roots", limit: "Trusts an order's arbiter, where the employer named one", detail: "Trusted for: Deciding a disputed delivery claim, with no evidence required on chain. If it fails: It can decide either way. Only that order is affected, and only once a claim has been challenged." },
  { launch: "B", id: "T8", section: "Trust roots", limit: "Trusts the desk, as CrowdPots and the Doorbell see it", detail: "Trusted for: Reporting accountOf honestly and pushing what it reports. It is the same launch's immutable code. If it fails: As a second line, CrowdPots checks what the desk does at launch and refuses to book more than it holds." },
  { launch: "B", id: "T9", section: "Trust roots", limit: "Trusts the launch pipeline and the ProjectFactory", detail: "Trusted for: Creating the four contracts with the manifest's arguments, in order. The pipeline audits the code first and may change it before deploying, as it did for our first launch (section 11). If it fails: A wrong argument is permanent. docs/LAUNCH.md says how to read every argument back after the launch." },
  { launch: "B", id: "T10", section: "Trust roots", limit: "Trusts runners, keepers and challengers", detail: "Trusted for: Liveness only. Nothing on the desk ends by itself. If it fails: With nobody calling, orders wait: escrows stay where they are and can always be returned by anyone once the time has come." },
  { launch: "B", id: "T11", section: "Trust roots", limit: "Trusts OpenZeppelin Contracts 5.5.0 (vendored in lib/) and solc 0.8.26", detail: "Trusted for: Correctness of the library code and the compiler." },
  { launch: "B", id: "P1", section: "Limits of WorkProof", limit: "A proof says what IdentityMD recorded, and binds three things.", detail: "The template name (kind), the objective text and the final state. It says nothing about whether the work is good, and nothing about a job's other inputs: a repository and commit, the steps of a plan, a rubric, the size of a panel." },
  { launch: "B", id: "P2", section: "Limits of WorkProof", limit: "Only a job's latest receipt proves.", detail: "The registry holds one hash per job. A job can be given a second receipt (IdentityMD wrote one when work was delivered to a repository, for the jobs we saw from 27 September); the first then stops proving." },
  { launch: "B", id: "P3", section: "Limits of WorkProof", limit: "A second receipt names no agents.", detail: "The proving record of a job that has one carries an empty signals list, so a settlement made after it tips nobody in particular: the tip goes to Payroll with an empty list, which the live Payroll books to its seat pool." },
  { launch: "B", id: "P4", section: "Limits of WorkProof", limit: "The record's form is fixed for good.", detail: "WorkProof accepts one canonical form, the one records had in October 2026: one object, no whitespace, keys ascending, top-level keys of 1 to 31 ASCII bytes, the job id a lowercase UUID, the schema string identitymd-work-v1." },
  { launch: "B", id: "P5", section: "Limits of WorkProof", limit: "The cost of a proof follows a record's shape, and structure has a ceiling.", detail: "Text costs 4 to 19 gas a byte whatever it holds. Between strings the walk costs up to about 195 gas a byte." },
  { launch: "B", id: "P6", section: "Limits of WorkProof", limit: "A record above about 128 KB does not fit one transaction's calldata.", detail: "It has to be stored first as data contracts for proveChunks, at 200 gas per byte of code: about 64 million gas over several transactions for the 318 KB record among the fixtures, against about 575,000 for the proof itself." },
  { launch: "B", id: "P7", section: "Limits of WorkProof", limit: "The scan stops at state.", detail: "What follows it (nine tenths of an audit record) is covered by the record hash and by nothing else; scan alone says nothing about those bytes. Nested values are stepped over, not validated, to any depth." },
  { launch: "B", id: "P8", section: "Limits of WorkProof", limit: "The list of agents is best effort.", detail: "At most 16, each once. An element that cannot be read empties the list and never fails a proof." },
  { launch: "B", id: "P9", section: "Limits of WorkProof", limit: "Some finished jobs have no record to prove.", detail: "Three completed research jobs of 6 and 7 October had no work record at all, and IdentityMD's documentation says oracle work is recorded once a day as one Merkle root for all of a day's jobs, not once a job." },
  { launch: "B", id: "P10", section: "Limits of WorkProof", limit: "The constructor takes any address.", detail: "A registry address with no code makes every proof NoReceipt. It fails safe; it is also permanent." },
  { launch: "B", id: "W1", section: "Limits of the hire desk", limit: "A runner bears the lateness of receipts.", detail: "On an order without the claimed path, a runner that opened the right job and saw it completed is paid only when the receipt is on chain. If none lands within the order's delivery time and somebody calls timeout, its bond goes to the employer and its 0.5 IMD swarm fee is spent." },
  { launch: "B", id: "W2", section: "Limits of the hire desk", limit: "The kind is the runner's risk, and a wrong kind costs it little.", detail: "A receipt with the right objective, state completed, under another kind can never settle the order. Anyone may report it; the order is free again and the bond returns to the runner, because the desk cannot tell a runner's wrong template from a kind the swarm renamed. A runner that picks a wrong template on purpose pays the swarm's fee each time and holds the order until the receipt lands. It is not barred from the order, so the same address can take it again at once and repeat this for as long as the order stays open." },
  { launch: "B", id: "W3", section: "Limits of the hire desk", limit: "Only the runner reports its own job's failure.", detail: "A receipt with the right objective and a state other than completed returns the whole bond to the runner, and only the runner may submit it: a job's first receipt need not be its last, and the runner decides whether to give up or to register a retry. A runner whose job failed can therefore keep its claim until just before the delivery deadline and still get its bond back. It cannot go past the deadline: timeout then takes the bond. Its claim can outlast the order's expiry, though: the report then refunds the order instead of reopening it, with the bond still returned whole." },
  { launch: "B", id: "W4", section: "Limits of the hire desk", limit: "A record WorkProof cannot read decides nothing.", detail: "If the registry holds a hash for a job whose record is not a canonical v1 work record, the record can be neither settled nor reported, and the claim ends by timeout." },
  { launch: "B", id: "W5", section: "Limits of the hire desk", limit: "One bond can keep an escrow out of reach for the delivery time.", detail: "A runner that registers a job and goes silent holds the order until registeredAt + deliverySecs, at most 90 days. It costs the runner its bond, which the employer receives, unless the runner ends the hold itself with a receipt that shows the job did not complete (W3), or anyone ends it with one of another kind (W2): then the bond comes back whole and the hold has cost the runner one swarm job." },
  { launch: "B", id: "W6", section: "Limits of the hire desk", limit: "A settlement must be offered more gas than it uses.", detail: "The desk refuses to start a Payroll call it cannot hand 1,000,000 gas to, so that no caller can push a payment onto the plain-transfer path by sending too little." },
  { launch: "B", id: "W7", section: "Limits of the hire desk", limit: "The tip reaches the agents only when the proving record names them.", detail: "Not after a second receipt (P3), and not on a delivery paid on a claim or by an arbiter, where the desk has no record to read. In those cases the tip goes to Payroll with an empty list." },
  { launch: "B", id: "W8", section: "Limits of the hire desk", limit: "A condition is latched on one true reading.", detail: "trigger, or the first claim, records that the condition held once, and it is never consulted again. An employer that points a condition at something a caller can make true for the length of one transaction (a spot balance, a pool price) lets that caller open the order." },
  { launch: "B", id: "W9", section: "Limits of the hire desk", limit: "accountOf(id).returned counts what the desk paid the employer as the employer.", detail: "Every such transfer is counted, exactly. Money the same address receives in another role, as its own order's runner or as a challenger, is not counted." },
  { launch: "B", id: "W10", section: "Limits of the hire desk", limit: "An employer may be its own runner, and its own arbiter.", detail: "Nothing stops an address from taking its own order or from naming itself arbiter. On the proven path it pays the 10% and the swarm's fee for doing so." },
  { launch: "B", id: "W11", section: "Limits of the hire desk", limit: "The callback cannot hire again.", detail: "150,000 gas records a delivery; it does not open an order. A callback that fails leaves the delivery as it is, and anyone can try it again with redeliver." },
  { launch: "B", id: "W12", section: "Limits of the hire desk", limit: "A spec is public and plain, and the desk does not know what the swarm will accept.", detail: "The whole job text is emitted in OrderOpened. It is 1 to 7,900 bytes of printable ASCII with no \" and no \\." },
  { launch: "B", id: "W13", section: "Limits of the hire desk", limit: "A job id is tied to an order only by a receipt, so two orders can have one job registered at the same time.", detail: "register reserves nothing, so copying somebody's job id onto another order blocks nobody. The job's receipt carries one claim's header and settles that claim's order alone." },
  { launch: "B", id: "L1", section: "Limits of the claimed path", limit: "An untrue delivery claim that nobody challenges within 24 hours is paid.", detail: "The job id and the record hash of a claim are the runner's word. What protects the employer is somebody watching and posting a bond equal to the runner's." },
  { launch: "B", id: "L2", section: "Limits of the claimed path", limit: "While receipts are late, a challenger can keep a true claim from being paid, and it costs the challenger only gas and the use of its bond until the deadline.", detail: "With no receipt and no arbiter decision by the delivery deadline, the employer is refunded, the challenger gets its bond back, and the runner loses a tenth of its bond to the employer." },
  { launch: "B", id: "L3", section: "Limits of the claimed path", limit: "What the rules do guarantee.", detail: "A runner whose challenged claim is not upheld never gets off more cheaply than by release, whoever the challenger was, its own second address included. Any valid receipt of the registered job pays the runner, in a dispute too, whatever hash it named, and cannot be used against it." },
  { launch: "B", id: "L4", section: "Limits of the claimed path", limit: "An arbiter is the answer for an employer that wants neither L1 nor L2.", detail: "Crowd pots and the Doorbell cannot name one (C3, D2)." },
  { launch: "B", id: "L5", section: "Limits of the claimed path", limit: "A receipt for a job that did not complete refutes a claim, even if a later receipt would have paid it.", detail: "In every job we saw with two receipts, both said completed. Whether IdentityMD can write a not-completed receipt first and a completed one later is not known." },
  { launch: "B", id: "L6", section: "Limits of the claimed path", limit: "A challenger's bond is held until the dispute ends, which can be 90 days, and a dispute that nothing decides pays the challenger nothing.", detail: "From challenge on, the bond leaves the desk only when a receipt, the order's arbiter or the delivery deadline ends the dispute; the deadline is registeredAt + deliverySecs, and an order's delivery time can be 90 days." },
  { launch: "B", id: "L7", section: "Limits of the claimed path", limit: "The first challenge to be mined is the only one.", detail: "A delivery claim can be challenged once. Somebody who sees a watcher's challenge waiting to be mined can send the same call ahead of it, with a bond of its own." },
  { launch: "B", id: "C1", section: "Limits of CrowdPots", limit: "Nothing on chain says the pot's kind is one the swarm writes.", detail: "Every pot names its kind in text, in its opening event and through kindOf, and the desk pins the hash of that text. A pot whose kind no work record carries can never be paid on a receipt." },
  { launch: "B", id: "C2", section: "Limits of CrowdPots", limit: "A pot that allows claims can be ended early, in a refund, for a tenth of the bond.", detail: "A pot hires once. One party with two addresses can take its order, claim delivery, challenge itself and wait out the delivery time; the pot is then refunded and over. On a receipt-only pot the same stall by silence costs the whole bond and the order is open again afterwards. A receipt-only pot can also be ended in a refund with no bond forfeited at all, whatever bond the opener chose. A runner takes the order shortly before its hire window closes and registers a job whose receipt does not say completed; only the runner may report that receipt (W3), so nobody can free the order sooner, and once the hire window has passed the report refunds the order and the pot with the bond returned whole. The same ending comes from a completed receipt of another kind (W2), which anyone may report and which bars nobody, so one address can cycle claim, register, wrong-template job and report on a pot's order for as long as its hire window lasts. Either costs the runner one swarm job and gas, and the contributors the time their IMD was locked. No IMD is lost." },
  { launch: "B", id: "C3", section: "Limits of CrowdPots", limit: "A pot's order has no reserved runner, no arbiter and no condition,", detail: "because a contributor could not judge them. There is no minimum bond relative to the target: a larger bond makes a stall dearer and a challenge harder, and the bond is the opener's published choice." },
  { launch: "B", id: "C4", section: "Limits of CrowdPots", limit: "A chip is locked while the pot runs.", detail: "There is no withdrawal while a pot collects. At the longest: 30 days of collecting, one day in which a full pot can still be launched, 30 days waiting for a runner, the desk's one-hour claim window and 30 days for delivery." },
  { launch: "B", id: "C5", section: "Limits of CrowdPots", limit: "reconcile and claimRefund end an overdue claim as soon as they can.", detail: "Any contributor's call has the desk time out a registered job whose delivery time has passed. A receipt that lands after that no longer pays that runner." },
  { launch: "B", id: "C6", section: "Limits of CrowdPots", limit: "The views cannot forecast an order a runner still holds past its time.", detail: "stageOf reads Hiring and refundOf reads zero until reconcile or claimRefund has had the desk end the claim. A simulated call of claimRefund gives the true figure." },
  { launch: "B", id: "C7", section: "Limits of CrowdPots", limit: "IMD sent to CrowdPots by plain transfer belongs to nobody", detail: "and stays there." },
  { launch: "B", id: "C8", section: "Limits of CrowdPots", limit: "Shares are rounded down, and the last claimer takes the remainder.", detail: "A later claimer can receive a few wei more than an earlier one with the same chip; the pot pays out to the wei." },
  { launch: "B", id: "C9", section: "Limits of CrowdPots", limit: "The pot's copy of the job id and record hash is a convenience.", detail: "It stays zero if the desk's callback never arrived, and on the claimed path it is the hash the runner named. Money is read from the desk's books and does not depend on it." },
  { launch: "B", id: "C10", section: "Limits of CrowdPots", limit: "A series cannot be closed, a chip sent to a series id goes to whichever round is collecting, and anyone's first chip starts a round's clock.", detail: "A chip meant for one round goes to that round's own id. A round collects for its fundSecs from its first chip, whoever sends it and however small: one wei from a stranger opens a round, and funders that come later have that much less of the round's time." },
  { launch: "B", id: "C11", section: "Limits of CrowdPots", limit: "A refund is paid when anybody asks, to the contributor and nobody else.", detail: "claimRefund and claimRefunds take the contributor as an argument and may be called by anyone, so a contributor that is a contract and cannot make the call is still paid. The other side of that: a contract contributor receives its refund at a moment somebody else chooses." },
  { launch: "B", id: "D1", section: "Limits of the Doorbell", limit: "Its IMD can never be withdrawn.", detail: "It leaves only as the escrow of the Doorbell's own orders. Fund it with small amounts." },
  { launch: "B", id: "D2", section: "Limits of the Doorbell", limit: "With the claimed path on, everything it holds is open to delivery claims that nobody challenges.", detail: "Anyone can ring it to a hire, take the order, claim delivery and be paid 24 hours later unless somebody posts 0.25 IMD to challenge, each time. And a challenge nothing decides refunds the order even when the claim was true. It has no arbiter and no reserved runner. This is the setting docs/LAUNCH.md recommends while receipts are stalled, for the reason given there; whoever funds the Doorbell should have a keeper watching its orders with 0.25 IMD for each claim it may have to challenge. No watcher is running. On 15 October 2026 the team's keeper, the bot that can challenge an untrue claim, is not hosted: the team runs it by hand and has no other watcher, and we know of nobody else who watches the Doorbell's orders. At block 26,200,224 that day the Doorbell held no IMD, so it could open no order until somebody funds it." },
  { launch: "B", id: "D3", section: "Limits of the Doorbell", limit: "With the claimed path off, a wrong kind or a header the swarm does not keep means no order is ever paid.", detail: "Each ends in a refund, the next 25th ring orders again, and the IMD stays in the Doorbell for good. The swarm kept the header and wrote the template as the kind for the one job we bought with a header, a research report; that has not been shown for a picture job, which is what the Doorbell orders (docs/LAUNCH.md, section 5). And with the path off nothing is paid for as long as IdentityMD's writer writes no receipts. Shown since, on 14 October 2026, for a picture job: the job bought for order 1, the Doorbell's own, kept the header byte for byte, its record carries skill:create-image as its kind, and the desk settled the order on its receipt." },
  { launch: "B", id: "D4", section: "Limits of the Doorbell", limit: "Its only limit is its balance.", detail: "There is no daily cap. 25 rings and one escrow per order. A 25th ring that comes while the Doorbell holds less than one escrow is counted and hires nothing; the next chance is 25 rings later." },
  { launch: "B", id: "D5", section: "Limits of the Doorbell", limit: "Nothing checks the picture.", detail: "The spec asks for the day's date in a corner. No contract looks at what was drawn." },
  { launch: "B", id: "B1", section: "Limits of the build and of its tests", limit: "One real swarm job has carried an order header; no order has been settled by a real job.", detail: "On 13 October 2026 we bought one job, e70c56ce-60f0-4c2c-b413-67e5ae37ddce, a research report whose objective began with 85 bytes shaped like an order header. Shown since, on 14 October 2026: IdentityMD's real writer wrote the header job's receipt (block 26,189,975), and order 1 of the launched desk, a picture job the Doorbell opened, was settled on the proven path against a receipt the real writer had written a minute before (blocks 26,190,218 and 26,190,223). That order's header was the header of an order on the deployed desk, and its job was a picture job (README.md has the transactions). On 16 October 2026 order 2, a research report that a contract of launch C (Rules) opened and that only a receipt can pay, was settled on the proven path against a receipt IdentityMD's writer wrote two blocks before the runner registered the job (blocks 26,204,533 and 26,204,543)." },
  { launch: "B", id: "B2", section: "Limits of the build and of its tests", limit: "Payroll is a stand-in in the tests that run without a network, and the live contract in the fork suite.", detail: "The stand-in does what the launched pay, tip and book do and can be made to fail in eight ways." },
  { launch: "B", id: "B3", section: "Limits of the build and of its tests", limit: "The registry is a stand-in in the default suite", detail: ". The fork suite uses the real one." },
  { launch: "B", id: "B4", section: "Limits of the build and of its tests", limit: "Two contracts in the place of a sibling remain, on purpose.", detail: "test/pots/mocks/OddDesk.sol is a desk that breaks its own interface (pulls less than asked, reuses an order id, names another employer, over-reports), which the real desk cannot do; it is used only to reach the checks CrowdPots and the Doorbell make on the desk's answers." },
  { launch: "B", id: "B5", section: "Limits of the build and of its tests", limit: "21 of the 41 records examined are stored,", detail: "covering 18 of the 20 kinds seen. Each stored record has a stated role in test/fixtures/proof/index.json; the other 20 are listed there with their hashes and can be fetched again." },
  { launch: "B", id: "B6", section: "Limits of the build and of its tests", limit: "The launch is 11.04 million gas in our rehearsal,", detail: "against our gate of 12 million and the protocol's ceiling of 16.7 million." },
  { launch: "B", id: "B7", section: "Limits of the build and of its tests", limit: "Nothing is called after deployment,", detail: "and nothing needs to be: the first order, the first pot and the first ring are calls anyone may make." },
  { launch: "B", id: "B8", section: "Limits of the build and of its tests", limit: "One byte of the desk's runtime code reads as ORIGIN to a scanner that does not tell code from data.", detail: "It lies in the constant data after the last instruction. The desk never uses tx.origin." },
  { launch: "B", id: "B9", section: "Limits of the build and of its tests", limit: "With the IR pipeline, whether a large test function compiles can depend on which files are compiled in the same run.", detail: "We met this once, in the test helper that builds records, and moved that helper behind a contract. The four contracts under src/ compiled in every configuration we ran: the whole project, src/ alone, the default test set and the fork set." },
  { launch: "B", id: "B10", section: "Limits of the build and of its tests", limit: "forge build prints advisory notes from Foundry's linter", detail: "for comparisons with block.timestamp, events emitted after a call, and the two partial reads of accountOf. They are the same matters as the Slither findings explained below." },
  { launch: "B", id: "B11", section: "Limits of the build and of its tests", limit: "The code is the code that was reviewed.", detail: "The four contracts' creation and runtime code are byte for byte what they were when this project was assembled as one and reviewed (12 October 2026)." },
  { launch: "B", id: "N1", section: "Not verified", limit: "Shown since this list was written", detail: "(15 October 2026): a proof on chain for a job that carried an order header (the research-report job of B1, whose receipt was written on 14 October), and an order settled by a real job on the proven path: order 1, a picture job opened by the Doorbell, settled on 14 October with a receipt written by IdentityMD's real writer, which settles the Doorbell's kind on the proven path as well (README.md has the transactions). On 16 October 2026 a second order was settled the same way: order 2, a research report whose employer is a contract (Rules, launch C) and that only a receipt can pay, with the employer's callback run in the same transaction after the payments, and the 0.03995 IMD the order did not spend returned to that employer. What follows is still not shown." },
  { launch: "B", id: "N2", section: "Not verified", limit: "The live Payroll under a real failure.", detail: "It has none a caller can cause; the failures in the fork suite are imposed from outside (B2)." },
  { launch: "B", id: "N3", section: "Not verified", limit: "The launch pipeline itself", detail: "was not ours to run. It ran on 13 October 2026 and changed no compiled code: it corrected three comments in src/pots/CrowdPots.sol (ADAPTATION.md; docs/AUDITS.md, row 9); before that, the factory call was rehearsed on a fork as the launch deployer." },
  { launch: "B", id: "N4", section: "Not verified", limit: "Whether a not-completed receipt can be followed by a completed one", detail: "(L5), and whether IdentityMD still writes second receipts." },
  { launch: "B", id: "N5", section: "Not verified", limit: "Whether a transaction with more than 128 KB of calldata can reach a block,", detail: "and the on-chain cost of storing a record as data contracts." },
  { launch: "B", id: "N6", section: "Not verified", limit: "The kind strings of skills that have no receipt yet.", detail: "" },
  { launch: "B", id: "N7", section: "Not verified", limit: "That the registry holds no DELEGATECALL and what its admin can do,", detail: "beyond the reading named in section 2." },
  { launch: "B", id: "N8", section: "Not verified", limit: "No audit by anyone outside IdentityMD's network.", detail: "The launch pipeline's audit agents and an independent reviewer read the code before it was deployed (ADAPTATION.md). Before that: two internal reviews per contract when the contracts were written, their findings fixed or listed above, a second read of the code changed since, the review of section 11, and the checks in this repository." },
  { launch: "B", id: "N9", section: "Not verified", limit: "Gas figures", detail: "are from tests and from a mainnet fork, apart from those of orders 1 and 2 on mainnet: order 1's ring that hired used 328,183 gas and its settlement 636,569; order 2's claim used 114,598, its registration 41,748 and its settlement 488,072, with a 3,801-byte record." },
  { launch: "C", id: "T1", section: "Trust roots", limit: "Trusts the IMD token, 0xd34a99bc0f67ae1bbd63c660e6d0b0dd03e263b7, and its owner, 0x047F606fD5b2BaA5f5C6c4aB8958E45CB6B054B7: the same account as the WorkRegistry's admin (launch B's docs/THREATS.md, T1)", detail: "Trusted for: Moving exactly the amount it is asked to: no fee on transfer, no hooks. If it fails: Rules does not measure what arrived when a rule is funded; a token that kept part of each transfer would leave the escrows above the balance. Endowments does measure. IMD on Ethereum is a LayerZero OFT (BridgedFP), not a proxy: its supply here is created only when LayerZero's endpoint delivers a transfer from the contract the token names as its peer on another chain. The owner names those peers (setPeer) and who sets how their messages are verified (setDelegate; the delegate is the owner itself), so it can have IMD created on Ethereum through a contract of its choosing. New IMD changes no escrow Rules holds and no principal or share Endowments holds, only what each is worth." },
  { launch: "C", id: "T2", section: "Trust roots", limit: "Trusts the sIMD vault, 0x9efa934d9fad4ae28c998a40195646b965a97247: a Solady ERC-4626 over IMD whose owner is the zero address", detail: "Trusted for: Holding everything Endowments has staked, and doing what its previews say. If it fails: A loss inside the vault is shared by the depositors of each endowment in proportion (E2)." },
  { launch: "C", id: "T3", section: "Trust roots", limit: "Trusts Permit2, 0x000000000022d473030f116ddee9f6b43ac78ba3, to which sIMD gives a standing allowance over every holder's shares", detail: "Trusted for: Moving tokens only with the holder's approval inside Permit2 or the holder's signature. If it fails: Endowments can give neither: it never calls Permit2 and has no signature check." },
  { launch: "C", id: "T4", section: "Trust roots", limit: "Trusts Questions (launch A), 0xEECE4628ceb091C13393fc64056Be8b8501fD3F6", detail: "Trusted for: For a meter endowment: stating a feed's cost and its meter honestly, and crediting what it is sent. For Zap: crediting the meter shares to the address Zap names." },
  { launch: "C", id: "T5", section: "Trust roots", limit: "Trusts the source of a FEED rule: whatever contract the rule's creator named, normally Questions", detail: "Trusted for: Answering latest(feedId) truthfully: the value, the round and the time of the answer. If it fails: Rules believes it." },
  { launch: "C", id: "T6", section: "Trust roots", limit: "Trusts WorkOrders, the hire desk (launch B), 0x730CB6C845d896e33283d3A4Ed8967F8BAA778d2", detail: "Trusted for: Reporting accountOf(orderId) honestly: returned counts every IMD transfer the desk makes to the employer for that order, each exactly once. Pulling exactly the order's maxPay. Never reusing an order id." },
  { launch: "C", id: "T7", section: "Trust roots", limit: "Trusts everything behind the desk: IdentityMD's WorkRegistry and its writer, runners, challengers, an order's arbiter", detail: "Trusted for: Deciding whether an order of a HIRE rule is paid. If it fails: An order's escrow is on the desk and follows the desk's rules, which launch B's docs/THREATS.md sets out. The registry's writer wrote no receipt from about 8 October until 13 October 2026, 17:26 UTC (R14)." },
  { launch: "C", id: "T8", section: "Trust roots", limit: "Trusts CrowdPots (launch B), 0x8C2FfCdcb103659aa05c772b8F2059868B496EB5", detail: "Trusted for: For a pot endowment: saying what a pot still needs and taking a chip in the beneficiary's name. For Zap: the same, in the caller's name." },
  { launch: "C", id: "T9", section: "Trust roots", limit: "Trusts Uniswap v4's PoolManager, 0x000000000004444c5dc75cb358380d2e3de08a90, and the ETH/IMD pool", detail: "Trusted for: Calling back only the contract that asked it to unlock, and refusing to finish unless every amount owed is settled. The pool's price is not trusted: the caller states the least it accepts." },
  { launch: "C", id: "T10", section: "Trust roots", limit: "Trusts a VIEW rule's target: any contract the rule's creator named", detail: "Trusted for: Nothing. If it fails: It is untrusted. It is read with a static call and 100,000 gas; a revert, a burn of all its gas, too few bytes or no code only mean the rule does not fire." },
  { launch: "C", id: "T11", section: "Trust roots", limit: "Trusts a rule's creator, and an endowment's creator", detail: "Trusted for: The creator of a rule chooses everything about it and can cancel it at any time. The creator of an endowment chooses its target and, for a pot, its fallback beneficiary, once and for good." },
  { launch: "C", id: "T12", section: "Trust roots", limit: "Trusts keepers", detail: "Trusted for: Liveness only. Nothing here runs by itself. If it fails: With nobody calling: deposits wait unstaked and stay withdrawable, yield stays staked, rules do not fire, returns from the desk wait to be reconciled." },
  { launch: "C", id: "T13", section: "Trust roots", limit: "Trusts the launch pipeline and the ProjectFactory", detail: "Trusted for: Creating the three contracts with the manifest's arguments, in order. If it fails: A wrong argument is permanent. docs/LAUNCH.md says how to check each address before the launch and how to read every argument back after it." },
  { launch: "C", id: "T14", section: "Trust roots", limit: "Trusts OpenZeppelin Contracts 5.5.0 (vendored in lib/) and solc 0.8.26", detail: "Trusted for: Correctness of the library code and the compiler." },
  { launch: "C", id: "R1", section: "Limits of Rules", limit: "Any VIEW condition is accepted, including one a caller can make true for the length of one transaction.", detail: "Rules does not judge conditions. A creator who points a rule at a spot balance, a pool price or anything else that can be moved and moved back lets whoever wants the tip make it true, fire the rule and undo the move." },
  { launch: "C", id: "R2", section: "Limits of Rules", limit: "A condition is read when the rule is fired, and only then.", detail: "One true reading fires it. There is no latch and no second look: a PAY rule's money moves in that transaction." },
  { launch: "C", id: "R3", section: "Limits of Rules", limit: "A FEED rule believes its source.", detail: "The rule's creator names the contract that is asked for latest(feedId); a later Questions deployment needs no new Rules, and by the same token a source that is not Questions at all is believed just as much." },
  { launch: "C", id: "R4", section: "Limits of Rules", limit: "Only fire insists on the condition's gas.", detail: "fire reverts GasShort unless the target can be offered the whole 100,000 gas, so the sender of a transaction cannot choose the answer of a target whose answer depends on gas." },
  { launch: "C", id: "R5", section: "Limits of Rules", limit: "What a HIRE rule's creator fixes, it fixes for every order the rule opens.", detail: "The job text, the kind, the price range, the bond, the delivery time, a reserved runner, an arbiter and the flags are stored once." },
  { launch: "C", id: "R6", section: "Limits of Rules", limit: "With the claimed-path flag, the creator accepts the desk's bonded claims for every order of the rule.", detail: "A runner's statement that the job was delivered is paid after 24 hours unless somebody posts a bond equal to the runner's to challenge it, and an untrue claim that nobody challenges is paid." },
  { launch: "C", id: "R7", section: "Limits of Rules", limit: "Money comes back from the desk only as the desk reports it.", detail: "reconcile credits the difference between the desk's returned figure and what was already credited, never a change in balance. The limits of that are in T6." },
  { launch: "C", id: "R8", section: "Limits of Rules", limit: "Returns for a cancelled rule go to its creator, not to the rule.", detail: "cancel ends the rule for good; orders it opened stay on the desk, and what they return later is sent straight to the creator by whoever calls reconcile." },
  { launch: "C", id: "R9", section: "Limits of Rules", limit: "The delivery callback is a convenience.", detail: "A rule that set the desk's callback flag gets the change of a delivered order inside the settlement, in about 62,000 of the 150,000 gas the desk allows. Erratum, 15 October 2026. R9 is inexact in two places; the code is as it was deployed. The desk calls onWorkDelivered after a settlement, not inside it: settle, finalize, resolve when it finds for the runner, and redeliver each call it last, in the same transaction, once every payment is made and the desk's lock is released. A callback that fails undoes nothing: the desk records CallbackFailed, and anyone may call redeliver or reconcile later. The comment on onWorkDelivered in src/rules/Rules.sol says the desk calls it \"inside a try\"; the desk makes a plain call with the whole 150,000 gas instead, to the same effect. And 62,000 gas is what the callback used against this project's stand-in desk. Against the real desk, in this project's integration/ tests, it used 24,860 gas for a proven delivery and 28,681 for a cancelled rule's change, read from their traces on 15 October 2026." },
  { launch: "C", id: "R10", section: "Limits of Rules", limit: "A tip is paid for every fire, whatever becomes of the order.", detail: "A keeper can fire a HIRE rule whose order nobody then takes. The order's escrow returns; the tip does not." },
  { launch: "C", id: "R11", section: "Limits of Rules", limit: "Smaller points.", detail: "Anyone may add to a rule's escrow, and what they add becomes the creator's on cancel. A rule may be created with less than one fire's cost and then waits. A fire that would cost more than 2^96 wei is refused at creation. Rule ids are handed out in order: read a new rule's id from its RuleCreated event. The job text of a HIRE rule is public from the moment the rule is created. createRule refuses condition fields a rule does not use, but not action fields: a HIRE rule created with a PAY half, or a PAY rule with a HIRE half, stores only its own half, while RuleCreated publishes the caller's whole parameters, the unused half included. No money moves on that half. Read a rule's terms with getRule, not from the event. IdentityMD's reviewers raised this before the launch (docs/AUDITS.md, row 7); it was added here on 15 October 2026, after the launch, and two tests added the same day show it." },
  { launch: "C", id: "R12", section: "Limits of Rules", limit: "The tip is the first firer's.", detail: "Whoever's fire is mined first is paid the tip; a keeper whose transaction somebody copies and has mined ahead loses its gas, and its own transaction reverts having moved nothing. The rule's recipient or order is served once either way, and no caller can take more than the tip. There is no earlier party a tip could be kept for: firing is the whole of the work." },
  { launch: "C", id: "R13", section: "Limits of Rules", limit: "A creator's cancel races every keeper once the condition holds.", detail: "Whichever is mined first decides: a fire spends one fire's cost and the cancel returns the rest, or the cancel returns everything and the fire reverts. A creator who wants a rule never to fire again should cancel it before its condition can hold." },
  { launch: "C", id: "R14", section: "Limits of Rules", limit: "A HIRE rule's order without the claimed path waits on IdentityMD's receipts.", detail: "The desk pays only when the WorkRegistry holds the job's receipt, and a receipt that arrives after the order's delivery deadline cannot pay if somebody has had the order timed out first (launch B's docs/THREATS.md, W1). The registry wrote no receipt from about 8 October 2026 until 13 October, 17:26 UTC. It then worked through its backlog, and on 14 October the desk's first order was paid on its job's receipt, written that day. On 16 October the order of rule 1 (order 2) was paid the same way, on a receipt written two blocks before its runner registered the job. What the rule loses when a receipt is late is the tip of the fire and the order's time: the escrow comes back through reconcile, with the runner's bond, which the desk forfeits to the employer." },
  { launch: "C", id: "E1", section: "Limits of Endowments", limit: "What the principal guarantee covers.", detail: "A depositor can take back exactly the IMD it put in, to the wei, in whole or in pieces, whenever it likes, and nobody else can move it: not the endowment's creator, not its target, not a keeper. harvest takes only shares an endowment holds beyond what its principal needs, plus a margin." },
  { launch: "C", id: "E2", section: "Limits of Endowments", limit: "What it does not cover.", detail: "A loss inside sIMD. Deposits that were still waiting to be staked when the loss happened. The block of a hold (E3), in which principal leaves as sIMD shares or waits one block. The state right after a loss has been made good. Earnings. The seed (0.000001 IMD, paid by the creator), and anything given with donate. IMD's own value, and anything that happens to the IMD token itself." },
  { launch: "C", id: "E3", section: "Limits of Endowments", limit: "In a block where sIMD holds the contract, only buffered IMD can be withdrawn as IMD.", detail: "That is the block of this contract's own stake (at most one block in fifty), and any block in which somebody deposits into sIMD in this contract's name or sends it freshly minted shares." },
  { launch: "C", id: "E4", section: "Limits of Endowments", limit: "The price mark sees a fall only from a price that stake or harvest ran at.", detail: "Both record the highest sIMD price they have seen and refuse to run below it, so that after a fall no more IMD enters the vault and yield is kept as cover." },
  { launch: "C", id: "E5", section: "Limits of Endowments", limit: "A meter endowment's harvests are final, and the runway bounds them only so far.", detail: "Harvested IMD becomes meter shares that Endowments holds and never redeems; nothing in the contract calls defund. So that a feed which has stopped asking cannot absorb an endowment's yield without end, a harvest never lifts a meter above the cost of thirty requests at Questions.costOf, and the rest stays staked. What that rule does not do: The cost is the feed's own: the Intake's price plus the keeper tip that whoever created the feed set (0.5 and 0.05 IMD for the house feeds). A feed with a large tip has a large runway, and the tip of every answered round is paid out by Questions to the keeper that opened the round, however the answer arrives: IdentityMD's pipeline set that rule in launch A before deploying it (section 10). It bounds what a harvest adds, not what a meter holds. Anyone can fill the room with IMD of their own. A meter is shared. While Questions states no cost for the feed (the Intake is not selling its action, or asks more than the feed's cap), nothing is harvested and no meter endowment can be created for it. Launch A's Payroll tops its house feeds' meters up to a runway of its own, 14 or 4 requests, counted from its own meter shares (Questions.redeemable), so an endowment that keeps a meter full does not take Payroll's place. The endowment's runway counts the whole meter, Payroll's IMD included: on a house meter that Payroll keeps topped up, a harvest has room for thirty requests less what Payroll holds there. This follows from the two contracts' rules as written; no test here runs them together." },
  { launch: "C", id: "E6", section: "Limits of Endowments", limit: "A pot endowment's fallback beneficiary is a party to trust.", detail: "Every chip is made in the beneficiary's name, so every refund or change the pot pays goes to them. They receive the whole harvest whenever the pot takes no chips: it is full, launched, out of time, cannot be read, or reverts." },
  { launch: "C", id: "E7", section: "Limits of Endowments", limit: "A pot harvest must be sent with more gas than it uses.", detail: "It reverts LowGas unless the pot can be handed its whole 500,000 gas, so that a caller cannot starve the pot and push the yield to the fallback. The least gas that passes was 784,667 with the real IMD and sIMD; 850,000 is the limit to send. Unlike a meter, a pot is sent what it still needs however little that is: a pot one wei short of full is sent one wei, and the harvest costs its caller this gas to move it. MIN_HARVEST (0.001 IMD) bounds the yield a harvest is run for, not the part a pot takes. Nothing is lost. IdentityMD's reviewers raised this before the launch (docs/AUDITS.md, row 4); it was added here on 15 October 2026, after the launch." },
  { launch: "C", id: "E8", section: "Limits of Endowments", limit: "A recipient can be any address but six.", detail: "The zero address, Endowments itself, IMD, sIMD, Questions and CrowdPots are refused, because IMD sent there by plain transfer would be lost or, for sIMD, shared with whoever staked a block earlier. Any other contract is accepted, including one that cannot move IMD on, and a harvest, which anyone may call, pays it. The list cannot be complete: Endowments does not know the hire desk, Payroll or WorkProof, where IMD sent by plain transfer would also stay; launch B's auditors noted the same of CrowdPots.chipInFor." },
  { launch: "C", id: "E9", section: "Limits of Endowments", limit: "Targets are checked once, at creation.", detail: "A meter endowment needs a feed Questions states a cost for; a pot endowment needs a pot or series that already exists. Endowment ids are handed out in order: read a new id from its Created event and deposit to that id, not to a predicted one. A pot that exists but already needs nothing (it is full, launched or out of time) is accepted, where a feed that cannot be asked is refused. Such an endowment pays every harvest to its fallback beneficiary (E6), while its Created event names a pot as its target. A depositor should read what the pot still needs (CrowdPots.remaining) before depositing. IdentityMD's reviewers raised this before the launch (docs/AUDITS.md, row 6); it was added here on 15 October 2026, after the launch, and a test added the same day shows it." },
  { launch: "C", id: "E10", section: "Limits of Endowments", limit: "Dust, and tokens sent directly.", detail: "IMD is accounted for to the wei. sIMD shares are not: the split of a staked batch between endowments rounds down and leaves under one share-wei per endowment per batch (about 0.000008 IMD-wei) booked to nobody." },
  { launch: "C", id: "E11", section: "Limits of Endowments", limit: "Sizes that assume today's order of magnitude.", detail: "SEED, MARGIN and SPARE assume a share-wei is worth less than an IMD-wei, which holds until sIMD's price is more than a hundred thousand times today's." },
  { launch: "C", id: "E12", section: "Limits of Endowments", limit: "Waiting.", detail: "A deposit earns nothing for its endowment until the next stake, up to 50 blocks away and only when somebody calls it. harvestable and harvest of a meter endowment revert if Questions cannot be read." },
  { launch: "C", id: "Z1", section: "Limits of Zap", limit: "Price protection is the caller's own: the minimum out and the deadline.", detail: "Zap swaps on one pool and sets no limit of its own. A caller who passes a minimum of zero accepts any price, and a transaction can be reordered around; a caller who passes a far deadline accepts being mined at any time." },
  { launch: "C", id: "Z2", section: "Limits of Zap", limit: "The whole of the ETH is swapped before the pot is asked what it needs.", detail: "If the pot needs less, the surplus comes back to the caller as IMD in the same call, bought at the pool's price and fee. A pot that takes nothing at all reverts the call, so the caller keeps its ETH." },
  { launch: "C", id: "Z3", section: "Limits of Zap", limit: "The pool is fixed, and its cost is not Zap's to set.", detail: "The liquidity providers' fee is 1%. Uniswap's protocol fee comes on top (it read 0.1% on 13 October 2026) and can be changed by Uniswap's governance." },
  { launch: "C", id: "Z4", section: "Limits of Zap", limit: "What reaches Zap from outside goes to the next caller that can take it.", detail: "Zap has no receive, but ETH can be forced into any address and anyone can transfer IMD to it. Each call ends by sending the caller Zap's whole balance of both. That includes IMD sent to Zap on purpose by the other two contracts. Neither refuses Zap's address: an endowment may name Zap as its recipient or its fallback beneficiary, and a PAY rule may name it as its recipient. Each harvest or payment then goes to whoever calls Zap next, and the caller of harvest or fire can be that caller in the same transaction. Only yield, or the PAY amount, is exposed this way, never a depositor's principal. Nobody should name Zap as a payee. IdentityMD's reviewers raised this before the launch (docs/AUDITS.md, row 5); it was added here on 15 October 2026, after the launch, and three tests added the same day show it." },
  { launch: "C", id: "Z5", section: "Limits of Zap", limit: "Zap does not open orders.", detail: "The hire desk makes whoever calls it the employer, who receives the refund, the change and the callback, and that must be the person who paid. buy hands over the IMD and the caller opens the order in its own name." },
  { launch: "C", id: "Z6", section: "Limits of Zap", limit: "What the caller is credited with is launch A's and launch B's to honour.", detail: "The meter shares are the caller's by Questions.fundFor and the chip by CrowdPots.chipInFor; Zap keeps neither." },
  { launch: "C", id: "B1", section: "Limits of the build and of its tests", limit: "In this repository's own suite, Questions, the hire desk and the crowd pots are stand-ins.", detail: "Their sources are two other repositories. The stand-ins are test/rules/mocks/MockDesk.sol, MockFeed.sol, MockPots.sol, MockQuestions.sol and test/endowments/mocks/MockQuestions.sol, MockCrowdPots.sol." },
  { launch: "C", id: "B2", section: "Limits of the build and of its tests", limit: "integration/ is not part of what a launch import builds.", detail: "It compiles sources from two folders beside this one and does not build without them. forge build, forge test and forge fmt --check run from the root do not reach it: the root's src, test and script are src/, test/ and script/, its remappings name only forge-std and OpenZeppelin, and a copy of this folder alone with invalid Solidity and unformatted code placed in integration/test built, passed every test and passed the format check (15 October 2026). Somebody has to run cd integration && forge test on the commits that are launched; docs/LAUNCH.md, section 5, makes it a step." },
  { launch: "C", id: "B3", section: "Limits of the build and of its tests", limit: "Even there, some things are stand-ins.", detail: "IMD, the sIMD vault and the PoolManager (the fork suite of the main project uses the real ones); IdentityMD's WorkRegistry and Intake (the test doubles of launches B and A); the oracle's key (a test key); Payroll behind the desk (launch B's stand-in)." },
  { launch: "C", id: "B4", section: "Limits of the build and of its tests", limit: "On the fork, the contracts of the earlier launches are the live ones; the swarm's job is not run.", detail: "The rehearsal through the real ProjectFactory deploys this launch against the live Questions, WorkOrders and CrowdPots, and test/launch/fork/LiveSiblings.fork.t.sol runs the first day of docs/LAUNCH.md against them with real IMD. Three things there are not what will happen on the day: the job's receipt is written into the real WorkRegistry by acting as the writer the registry names; the work record is a real IdentityMD record (job e9efec16, 7,339 bytes) with the order's job id and objective put in; and the yield a harvest sends is IMD transferred to the vault by the test, as the vault receives its yield, in place of days of real earnings." },
  { launch: "C", id: "B5", section: "Limits of the build and of its tests", limit: "The vault and the pool of the default suite are stand-ins checked against the real ones.", detail: "MockStakedIMD is put in the state the real vault was in at block 26,164,296, and a fork test compares its answers with the real vault's. The pool stand-in sells at a fixed rate; the real pool is used in test/rules/fork/RulesAndZapFork.t.sol." },
  { launch: "C", id: "B6", section: "Limits of the build and of its tests", limit: "The fork suite depends on a public RPC.", detail: "Every fork test skips itself when the node cannot be reached, and a skipped run shows nothing." },
  { launch: "C", id: "B7", section: "Limits of the build and of its tests", limit: "The launch is 7.91 million gas in our rehearsal,", detail: "against our gate of 12 million and the protocol's ceiling of 16.7 million. The rehearsal passes placeholder values for the record the factory stores (source commit, manifest hash, attestation hash) and an unused launch number." },
  { launch: "C", id: "B8", section: "Limits of the build and of its tests", limit: "Faults were planted to see the tests fail.", detail: "In a copy outside the repository, 42 single changes were made one at a time: to the runway, the deadline, the order a rule opens, each stand-in, and the calls into the real contracts. 40 failed at least one test." },
  { launch: "C", id: "B9", section: "Limits of the build and of its tests", limit: "forge build prints advisory notes from Foundry's linter", detail: "for names in capitals and similar matters." },
  { launch: "C", id: "I1", section: "Inherited from earlier launches", limit: "Receipts.", detail: "An order of a HIRE rule without the claimed path is paid only when IdentityMD's WorkRegistry holds the job's receipt. The registry's writer wrote nothing from about 8 October until 13 October 2026, 17:26 UTC (block 26,185,055). It has written again since (44 receipts in the 1,800 blocks up to block 26,197,394), and on 14 October the desk's first order was paid on its job's receipt, written that day. On 16 October it wrote the receipt of rule 1's order within a minute of the job completing, and the desk paid that order on it. It can stall again (R14)." },
  { launch: "C", id: "I2", section: "Inherited from earlier launches", limit: "The order header.", detail: "IdentityMD keeps a job's objective byte for byte with the desk's 85 header bytes in front: shown on a research report bought on 13 October, and on chain by the desk's first order, a picture job, which the desk paid on the proven path on 14 October, and by its second, the research report rule 1 opened, paid the same way on 16 October." },
  { launch: "C", id: "I3", section: "Inherited from earlier launches", limit: "The house feeds.", detail: "Launch A's three feeds were created and their first rounds bought; each was answered on 13 October 2026, the employers feed by the Intake's own callback. A FEED rule, and a meter endowment, are worth what their feed is worth, and a feed is asked only when somebody pays for a round." },
  { launch: "C", id: "I4", section: "Inherited from earlier launches", limit: "The Intake.", detail: "Launch A's Questions buys from version 2 of IdentityMD's Intake (0xa43e6f75ee006411f79ac1c84120606c2330de82), the one IdentityMD names for anything new. A Questions that cannot buy answers states no cost, and then no meter endowment can be created or harvested (E5)." },
  { launch: "C", id: "I5", section: "Inherited from earlier launches", limit: "What IdentityMD's pipeline changed.", detail: "In launch A: a round's keeper tip always goes to the keeper that opened the round; a silent round can be closed only after the answer's validity has also run out (36 hours, 5 minutes and 1 second for the house feeds); a seat held by a contract must claim its own payouts. In launch B: no compiled code; it corrected three comments in CrowdPots.sol. Section 10 takes each through this launch." },
  { launch: "C", id: "N1", section: "Not verified", limit: "Shown since this list was written", detail: "(15 October 2026), on mainnet. IdentityMD launch 1845 created the three contracts in one transaction, in block 26,198,165 at 13:18 UTC, and each holds the constructor arguments of the manifest (read back with cast call that day). The code at each address is the code built from this folder: bash scripts/repro.sh at the root of the HELP WANTED repository compares the two, and printed a match for all three. Before deploying, the pipeline's audit of the imported code, four specialist reviewers and a judge read the code and raised 13 findings, none marked blocking. The pipeline changed nothing under src/ (ADAPTATION.md), and docs/AUDITS.md lists every finding with what became of it. Four of them are limits this document stated in part or not at all; R11, E7, E9 and Z4 state them since. E7 cites a test this folder held before the review; for the other three, tests added on 15 October 2026 show what the reviewers showed. By block 26,198,957 the team's wallet W1 had created one endowment, for the meter of launch A's payrolls feed, deposited 1 IMD into it and called stake twice. No rule had been created by then, and nothing had gone through Zap. On 16 October 2026 the team's wallet H1 created rule 1, the first rule of docs/LAUNCH.md, fired it by hand, and cancelled it after its order was paid (the second entry below). On 19 October 2026 W1 withdrew the 1 IMD from that endowment, exactly; nothing was harvested, because sIMD's price did not move while it was staked. The entries below were written before the launch and are kept as they were, but for the first, the second, the third and the one on gas figures, which now say what was shown. This note answers the first of them, and adds to the one on an audit." },
  { launch: "C", id: "N2", section: "Not verified", limit: "These contracts on chain.", detail: "Written before the launch, when nothing of it had been deployed. Shown since: IdentityMD launch 1845 created the three contracts on 15 October 2026, in block 26,198,165 (the note above). The launch was rehearsed on a fork through the real ProjectFactory, with placeholder record fields; the pipeline's own checks before that call are not ours to run." },
  { launch: "C", id: "N3", section: "Not verified", limit: "A real swarm job for a rule's order, and a receipt written by IdentityMD.", detail: "On the fork the order of the first rule is settled on the live desk against the real WorkRegistry, but the receipt is written by acting as the registry's writer, for a real record whose job id and objective were replaced (B4). That a real job's receipt pays a desk order on chain was shown by launch B's first order on 14 October 2026, not by an order of a rule. Shown since, on 16 October 2026: rule 1 fired on the live hires feed and opened order 2 on the live desk. A real swarm job (42f26c64-eea9-46f2-822a-33547ec18abf, a research report) was bought for it. IdentityMD's own writer wrote the job's receipt in block 26,204,533, and the order was settled on the proven path in block 26,204,543, with the change returned to the rule in the desk's callback. The rule's creator, the wallet that fired it and the runner were all the team's own." },
  { launch: "C", id: "N4", section: "Not verified", limit: "A FEED rule on an answer newer than 13 October.", detail: "The fork reads the live hires feed's one answered round. Whether the feed is asked again, and when, depends on somebody paying for it. The mainnet fire of 16 October read that same answer (223, round 1)." },
  { launch: "C", id: "N5", section: "Not verified", limit: "integration/ in the launch pipeline.", detail: "It is run by hand (B2)." },
  { launch: "C", id: "N6", section: "Not verified", limit: "Real yield harvested.", detail: "No test waits for sIMD's own earnings: the tests add yield by transferring IMD to the vault, which is how the real vault receives it. The rate the first day counts on (0.16% in 4.6 days, 10 to 15 October 2026) is a reading of two blocks, not a promise." },
  { launch: "C", id: "N7", section: "Not verified", limit: "The pool on the day.", detail: "Depth and price are read at the fork's block. Nothing here says what a swap will return on launch day." },
  { launch: "C", id: "N8", section: "Not verified", limit: "A review by a second person of the changes made in the integration pass and in this one:", detail: "the runway in Endowments, the deadline in Zap, the first-day plan, the fork tests against the live contracts, section 10 and the documents around them. The integration pass's changes were read line by line by another engineer and 42 planted faults were run against them (B8); this pass changed no contract code." },
  { launch: "C", id: "N9", section: "Not verified", limit: "No third-party audit.", detail: "Two internal reviews per contract in the first wave, their findings fixed or listed above, and the checks in this repository." },
  { launch: "C", id: "N10", section: "Not verified", limit: "Gas figures", detail: "are from tests and from a mainnet fork, apart from those of rule 1 and its order on mainnet (16 October 2026): createRule used 365,124 gas and fire 348,583, against 374,586 and 400,806 on the fork, and the order's settlement 488,072 as a transaction, with a 3,801-byte record." },
];

/** A row as one run of text: the heading, then how the document goes on. */
export function limitText(row: DisclosedLimit): string {
  if (row.detail === "") return row.limit;
  return /^[,.;:]/.test(row.detail) ? `${row.limit}${row.detail}` : `${row.limit} ${row.detail}`;
}
